export interface Cohort {
  /** "2026-03" */
  id: string
  /** "Mar 2026" */
  label: string
  /** Users who signed up that month */
  size: number
  /**
   * Users still active in each month since signup, starting with month 0.
   * The list stops where the cohort hasn't reached the month yet: a missing
   * month is unknown, while 0 means nobody came back.
   */
  retained: number[]
}

/** Months since signup shown as columns: month 0 to month 11 */
export const PERIODS = 12

const labels = [
  'Dec',
  'Jan',
  'Feb',
  'Mar',
  'Apr',
  'May',
  'Jun',
  'Jul',
  'Aug',
  'Sep',
  'Oct',
  'Nov',
]

// Deterministic, so the server and the browser render the same numbers
function random(seed: number) {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/** A typical curve: a steep drop after month 0, then a slow decline */
const curve = [
  1, 0.44, 0.35, 0.3, 0.27, 0.25, 0.235, 0.22, 0.21, 0.2, 0.195, 0.19,
]
const sizes = [40, 610, 720, 680, 820, 900, 860, 940, 1010, 980, 1100, 1240]

function makeCohorts(): Cohort[] {
  const next = random(7)
  return sizes.map((size, i) => {
    const year = i === 0 ? 2025 : 2026
    const month = i === 0 ? 12 : i
    // Twelve monthly cohorts up to November 2026: the oldest has had all
    // twelve months, the newest only its first
    const reached = PERIODS - i
    let retained: number[]
    if (i === 0) {
      // The soft-launch cohort was small, and its last users left in
      // month 9: real zeros, not missing data
      retained = [40, 14, 9, 6, 4, 3, 2, 1, 1, 0, 0, 0]
    } else {
      // Later cohorts retain a little better as the product improves
      const lift = 0.92 + i * 0.022
      retained = []
      for (let k = 0; k < reached; k++) {
        if (k === 0) {
          retained.push(size)
          continue
        }
        const noise = 0.94 + next() * 0.12
        const n = Math.round(size * Math.min(1, curve[k] * lift * noise))
        retained.push(Math.min(n, retained[k - 1]))
      }
    }
    return {
      id: `${year}-${String(month).padStart(2, '0')}`,
      label: `${labels[i]} ${year}`,
      size,
      retained: retained.slice(0, reached),
    }
  })
}

export const cohorts = makeCohorts()

import { PERIODS } from './data'
import type { Cohort } from './data'

export type Mode = 'percent' | 'count'

/** One cell: a month the cohort hasn't reached yet, or its retention */
export type Cell =
  { kind: 'unavailable' } | { kind: 'value'; count: number; percent: number }

export function cellAt(cohort: Cohort, period: number): Cell {
  const count = cohort.retained.at(period)
  if (period >= cohort.retained.length || count === undefined)
    return { kind: 'unavailable' }
  return { kind: 'value', count, percent: (count / cohort.size) * 100 }
}

/**
 * Average retention per month, weighted by cohort size, over the cohorts
 * that have reached that month. Null when fewer than two have: one cohort's
 * number isn't an average, and a single small cohort would make it swing.
 */
export function averages(list: Cohort[]) {
  return Array.from({ length: PERIODS }, (_, period) => {
    const reached = list.filter((c) => period < c.retained.length)
    if (reached.length < 2) return null
    const users = reached.reduce((sum, c) => sum + c.size, 0)
    const kept = reached.reduce((sum, c) => sum + c.retained[period], 0)
    return {
      count: kept,
      users,
      percent: (kept / users) * 100,
      cohorts: reached.length,
    }
  })
}

/**
 * How strong a cell's color is, 0 to 1. Retention after month 0 sits
 * between 0 and about 50%, so the scale tops out at 60% to keep those
 * differences visible; month 0's 100% simply saturates.
 */
export const intensity = (percent: number) => Math.min(percent, 60) / 60

/** Dark text on light cells, light text on strong ones */
export const needsLightText = (percent: number) => intensity(percent) > 0.55

export const formatPercent = (p: number) =>
  p === 0 ? '0%' : p < 1 ? '<1%' : `${Math.round(p)}%`

export const formatCount = (n: number) => n.toLocaleString('en-US')

/**
 * A sentence comparing a cohort with the average at month 3, or at the
 * latest month it has reached if it's younger than that
 */
export function compare(cohort: Cohort, list: Cohort[]) {
  const period = Math.min(3, cohort.retained.length - 1)
  if (period < 1) {
    return `${cohort.label} signed up this month (${formatCount(cohort.size)} users), so there is no retention to compare yet.`
  }
  const own = cellAt(cohort, period)
  const avg = averages(list)[period]
  if (own.kind !== 'value' || !avg) return ''
  const diff = Math.round(own.percent) - Math.round(avg.percent)
  const versus =
    diff === 0
      ? 'the same as the average'
      : `${Math.abs(diff)} ${Math.abs(diff) === 1 ? 'point' : 'points'} ${diff > 0 ? 'above' : 'below'} the average of ${formatPercent(avg.percent)}`
  return `${cohort.label}: ${formatCount(own.count)} of ${formatCount(cohort.size)} users (${formatPercent(own.percent)}) were still active in month ${period}, ${versus}.`
}

import type { CSSProperties } from 'react'
import type { ColumnDef, Table } from '@tanstack/react-table'

import { cn } from '#/lib/utils'
import {
  averages,
  cellAt,
  formatCount,
  formatPercent,
  intensity,
  needsLightText,
} from './cohorts'
import type { Cell, Mode } from './cohorts'
import { PERIODS, cohorts } from './data'
import type { Cohort } from './data'

export interface CohortMeta {
  mode: Mode
  highlighted: string | null
  toggle: (id: string) => void
}

const getMeta = (table: Table<Cohort>) =>
  table.options.meta as unknown as CohortMeta

/** Diagonal lines for months a cohort hasn't reached; also in the legend */
export const hatch =
  'bg-[repeating-linear-gradient(135deg,color-mix(in_oklab,var(--muted-foreground)_30%,transparent)_0_1px,transparent_1px_5px)]'

/** The fill, one hue getting stronger with retention; set on the table */
const fill = (percent: number): CSSProperties => ({
  backgroundColor: `color-mix(in oklab, var(--cohort) ${Math.round(intensity(percent) * 100)}%, transparent)`,
})

/**
 * One retention cell. A month the cohort hasn't reached is hatched and
 * says so; a real zero is a plain cell that shows 0.
 */
export function RetentionCell({
  cell,
  mode,
  title,
  unavailable = 'Not reached yet',
}: {
  cell: Cell
  mode: Mode
  title: string
  /** What an unavailable cell means here */
  unavailable?: string
}) {
  if (cell.kind === 'unavailable') {
    return (
      <span
        title={`${title}: ${unavailable.toLowerCase()}`}
        className={cn(
          'flex h-9 items-center justify-center rounded-sm text-xs text-muted-foreground/70',
          hatch,
        )}
      >
        <span aria-hidden>–</span>
        <span className="sr-only">{unavailable}</span>
      </span>
    )
  }
  const zero = cell.count === 0
  return (
    <span
      title={`${title}: ${formatCount(cell.count)} users, ${formatPercent(cell.percent)}`}
      style={fill(cell.percent)}
      className={cn(
        'flex h-9 items-center justify-center rounded-sm text-xs tabular-nums',
        needsLightText(cell.percent) && 'font-medium text-white',
        // A hairline makes an empty-looking zero read as a value
        zero && 'text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]',
      )}
    >
      {mode === 'percent'
        ? formatPercent(cell.percent)
        : formatCount(cell.count)}
    </span>
  )
}

const average = averages(cohorts)

export const columns: ColumnDef<Cohort>[] = [
  {
    id: 'cohort',
    header: 'Cohort',
    cell: ({ row, table }) => {
      const meta = getMeta(table)
      const on = meta.highlighted === row.original.id
      return (
        <button
          type="button"
          aria-pressed={on}
          data-cohort={row.original.id}
          onClick={() => meta.toggle(row.original.id)}
          className="rounded-sm text-left font-medium whitespace-nowrap outline-none hover:underline focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-pressed:underline"
        >
          {row.original.label}
        </button>
      )
    },
    footer: () => (
      <span className="flex flex-col">
        <span className="font-medium whitespace-nowrap">Average</span>
        <span className="text-xs font-normal text-muted-foreground">
          weighted, %
        </span>
      </span>
    ),
  },
  {
    id: 'size',
    header: () => <span className="block text-right">Users</span>,
    cell: ({ row }) => (
      <span className="block text-right text-muted-foreground tabular-nums">
        {formatCount(row.original.size)}
      </span>
    ),
    footer: () => (
      <span className="block text-right text-muted-foreground tabular-nums">
        {formatCount(cohorts.reduce((sum, c) => sum + c.size, 0))}
      </span>
    ),
  },
  {
    id: 'months',
    header: () => (
      <span className="block text-center">Months since signup</span>
    ),
    columns: Array.from(
      { length: PERIODS },
      (_, period): ColumnDef<Cohort> => ({
        id: `m${period}`,
        header: () => (
          <span className="block text-center tabular-nums">{period}</span>
        ),
        cell: ({ row, table }) => (
          <RetentionCell
            cell={cellAt(row.original, period)}
            mode={getMeta(table).mode}
            title={`${row.original.label}, month ${period}`}
          />
        ),
        // Weighted by cohort size, over the cohorts that reached the month
        footer: () => {
          const avg = average[period]
          return (
            <RetentionCell
              cell={
                avg
                  ? { kind: 'value', count: avg.count, percent: avg.percent }
                  : { kind: 'unavailable' }
              }
              // Always a percentage: summed counts from different cohorts
              // don't mean anything on their own
              mode="percent"
              unavailable="Too few cohorts to average"
              title={`Average, month ${period}${avg ? ` (${avg.cohorts} cohorts)` : ''}`}
            />
          )
        },
      }),
    ),
  },
]

import {
  flexRender,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table'

import {
  Table,
  TableBody,
  TableCell,
  TableFooter,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { cn } from '#/lib/utils'
import { columns } from './columns'
import type { CohortMeta } from './columns'
import { cohorts } from './data'

const isMonth = (id: string) => /^m\d+$/.test(id)

export function CohortTable(meta: CohortMeta) {
  const table = useReactTable({
    data: cohorts,
    columns,
    getRowId: (cohort) => cohort.id,
    getCoreRowModel: getCoreRowModel(),
    meta,
  })

  // The cohort column stays put while the months scroll on small screens
  const sticky = 'sticky left-0 z-10 bg-background'

  return (
    <div
      // The one hue every retention cell is a shade of
      className="overflow-hidden rounded-md border [--cohort:var(--color-blue-600)] dark:[--cohort:var(--color-blue-500)]"
    >
      <Table className="min-w-[860px]">
        <TableHeader>
          {table.getHeaderGroups().map((group) => (
            <TableRow key={group.id} className="hover:bg-transparent">
              {group.headers.map((header) => (
                <TableHead
                  key={header.id}
                  colSpan={header.colSpan}
                  className={cn(
                    'h-8',
                    header.column.id === 'cohort' && sticky,
                    isMonth(header.column.id) && 'w-14 px-0.5',
                    header.column.id === 'months' && 'border-b',
                  )}
                >
                  {header.isPlaceholder
                    ? null
                    : flexRender(
                        header.column.columnDef.header,
                        header.getContext(),
                      )}
                </TableHead>
              ))}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {table.getRowModel().rows.map((row) => {
            const dimmed =
              meta.highlighted !== null && meta.highlighted !== row.id
            return (
              <TableRow
                key={row.id}
                aria-current={meta.highlighted === row.id ? 'true' : undefined}
                className={cn(
                  'border-0 transition-opacity hover:bg-transparent motion-reduce:transition-none',
                  dimmed && 'opacity-35',
                  meta.highlighted === row.id &&
                    'shadow-[inset_3px_0_0_var(--color-primary)]',
                )}
              >
                {row.getVisibleCells().map((cell) => (
                  <TableCell
                    key={cell.id}
                    className={cn(
                      'py-0.5',
                      cell.column.id === 'cohort' && sticky,
                      isMonth(cell.column.id) && 'px-0.5',
                    )}
                  >
                    {flexRender(cell.column.columnDef.cell, cell.getContext())}
                  </TableCell>
                ))}
              </TableRow>
            )
          })}
        </TableBody>
        <TableFooter className="bg-transparent">
          {table
            .getFooterGroups()
            .slice(0, 1)
            .map((group) => (
              <TableRow key={group.id} className="hover:bg-transparent">
                {group.headers.map((header) => (
                  <TableCell
                    key={header.id}
                    className={cn(
                      'py-1.5',
                      header.column.id === 'cohort' && sticky,
                      isMonth(header.column.id) && 'px-0.5',
                    )}
                  >
                    {header.isPlaceholder
                      ? null
                      : flexRender(
                          header.column.columnDef.footer,
                          header.getContext(),
                        )}
                  </TableCell>
                ))}
              </TableRow>
            ))}
        </TableFooter>
      </Table>
    </div>
  )
}
